import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BPKcPtvA.js";const f=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"docs/getting-started.md","filePath":"docs/getting-started.md"}'),s={name:"docs/getting-started.md"};function n(i,e,l,h,d,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="flash-firmware" tabindex="-1">Flash firmware <a class="header-anchor" href="#flash-firmware" aria-label="Permalink to &quot;Flash firmware&quot;">​</a></h2><p>The easiest way is the <a href="/flasher/">MeshCoreNG web flasher</a> for ESP32 boards.</p><p>For nRF52, RP2040 and STM32 boards, download the firmware from <a href="https://github.com/MichTronics/MeshCoreNG/releases" target="_blank" rel="noreferrer">GitHub Releases</a> and use the platform&#39;s normal flashing method (UF2, ZIP, HEX).</p><h2 id="connect-a-client" tabindex="-1">Connect a client <a class="header-anchor" href="#connect-a-client" aria-label="Permalink to &quot;Connect a client&quot;">​</a></h2><p>MeshCoreNG uses the same protocol as MeshCore. Use any existing MeshCore client:</p><ul><li><strong>Web</strong>: <a href="https://app.meshcore.nz" target="_blank" rel="noreferrer">app.meshcore.nz</a></li><li><strong>Android</strong>: <a href="https://play.google.com/store/apps/details?id=com.liamcottle.meshcore.android" target="_blank" rel="noreferrer">Google Play</a></li><li><strong>iOS</strong>: <a href="https://apps.apple.com/us/app/meshcore/id6742354151" target="_blank" rel="noreferrer">App Store</a></li><li><strong>Config tool</strong>: <a href="https://config.meshcore.io" target="_blank" rel="noreferrer">config.meshcore.io</a></li></ul><h2 id="start-with-defaults" tabindex="-1">Start with defaults <a class="header-anchor" href="#start-with-defaults" aria-label="Permalink to &quot;Start with defaults&quot;">​</a></h2><p>The default settings are safe for any network. You do not need to change anything to get a working repeater.</p><p>When you want to tune behavior, start with <a href="/docs/dense-mesh.html">Dense mesh</a> and check <code>get dense.stats</code> to understand what is happening on your network before changing anything.</p><h2 id="developer-setup" tabindex="-1">Developer setup <a class="header-anchor" href="#developer-setup" aria-label="Permalink to &quot;Developer setup&quot;">​</a></h2><ol><li>Install <a href="https://docs.platformio.org" target="_blank" rel="noreferrer">PlatformIO</a> in <a href="https://code.visualstudio.com" target="_blank" rel="noreferrer">Visual Studio Code</a>.</li><li>Clone the <a href="https://github.com/MichTronics/MeshCoreNG" target="_blank" rel="noreferrer">MeshCoreNG repository</a>.</li><li>Open the repository in Visual Studio Code.</li><li>Select a build environment for your board (e.g. <code>Heltec_v3_repeater</code>).</li><li>Build and upload.</li></ol>',12)])])}const g=t(s,[["render",n]]);export{f as __pageData,g as default};
